//refAssemblies: System.Diagnostics.Process.dll
using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.IO;
using System.Linq;

var Globals = new TCAdmin.Scripting.Engines.Addons.CSharpGameGlobals(); // DO NOT MODIFY THIS LINE

var root = (string)ThisService.RootDirectory;
var cluster = Path.Combine(root, "DoNotStarveTogether", "Cluster_1");

// Without a cluster token an online server stops at "E_INVALID_TOKEN ... Your Server Will Not Start" but its process
// stays alive, so refuse the start with the reason instead. An offline (LAN) cluster needs no token.
var tokenFile = Path.Combine(cluster, "cluster_token.txt");
var clusterIni = Path.Combine(cluster, "cluster.ini");
var offline = File.Exists(clusterIni) && File.ReadAllLines(clusterIni).Any(l => l.Replace(" ", "").Equals("offline_cluster=true", StringComparison.OrdinalIgnoreCase));
if (!offline && (!File.Exists(tokenFile) || File.ReadAllText(tokenFile).Trim().Length == 0))
{
    throw new Exception("The server needs a Klei cluster token. Create one at accounts.klei.com > Games > Game Servers (Don't Starve Together) > Add New Server (or in the game: Play > Account > Game Servers), then paste it in Configuration Files > Cluster token.");
}

// Linux: install the shared libraries the server needs and this host does not have.
if (System.OperatingSystem.IsLinux())
{
    var packages = new Dictionary<string, (string[] Apt, string[] Rpm)>
    {
        ["libcurl-gnutls.so.4"] = (new[] { "libcurl3-gnutls", "libcurl3t64-gnutls" }, new[] { "libcurl" })
    };
    Shell("ldconfig -p 2>/dev/null || /sbin/ldconfig -p", out var cache);
    foreach (var soname in packages.Keys.Where(so => !cache.Split('\n').Any(l => l.Trim().StartsWith(so + " (") && l.Contains("x86-64"))))
    {
        var candidates = packages[soname];
        ScriptConsole.WriteLine((object)(soname + " is missing on this host; installing it."));
        var apt = Shell("command -v apt-get", out _);
        var tool = apt ? "DEBIAN_FRONTEND=noninteractive apt-get install -y " : Shell("command -v dnf", out _) ? "dnf install -y " : "yum install -y ";
        var names = apt ? candidates.Apt : candidates.Rpm;
        var installed = names.Any(p => Shell(tool + p, out _));
        if (!installed && apt && Shell("apt-get update", out _)) installed = names.Any(p => Shell(tool + p, out _));
        if (!installed) throw new Exception(soname + " is missing and could not be installed. Install one of these packages on the host: " + string.Join(", ", names));
        ScriptConsole.WriteLine((object)("Installed " + soname + "."));
    }
}

// Runs a fixed command (no customer value ever reaches it).
bool Shell(string command, out string output)
{
    using (var process = Process.Start(new ProcessStartInfo("/bin/sh", new[] { "-c", command }) { RedirectStandardOutput = true, RedirectStandardError = true, UseShellExecute = false }))
    {
        output = process.StandardOutput.ReadToEnd() + process.StandardError.ReadToEnd();
        process.WaitForExit();
        return process.ExitCode == 0;
    }
}

using System;
using System.IO;
using System.Linq;
using System.Text;
using System.Text.RegularExpressions;

var Globals = new TCAdmin.Scripting.Engines.Addons.CSharpGameGlobals(); // DO NOT MODIFY THIS LINE

// Don't Starve Together downloads and updates its Workshop mods itself when they are listed in
// mods/dedicated_server_mods_setup.lua (ServerModSetup("<id>")), and loads the ones enabled in each shard's
// modoverrides.lua (["workshop-<id>"]={ enabled=true }). Add the item to both; the server downloads it the next
// time it starts. Players who join download the mod on their own.
string fileId = Convert.ToString(Dynamic.FileId).Trim();
if (!Regex.IsMatch(fileId, "^[0-9]+$")) throw new Exception("Unexpected Workshop id: " + fileId);
string root = (string)ThisService.RootDirectory;

// 1. The download list.
string setup = Path.Combine(root, "mods", "dedicated_server_mods_setup.lua");
Refuse(setup);
Directory.CreateDirectory(Path.GetDirectoryName(setup));
bool setupExisted = File.Exists(setup);
string setupText = setupExisted ? File.ReadAllText(setup) : "";
if (Regex.IsMatch(setupText, @"^\s*ServerModSetup\(\s*[""']" + fileId + @"[""']\s*\)", RegexOptions.Multiline))
{
    ScriptConsole.WriteLine((object)("mods/dedicated_server_mods_setup.lua already lists " + fileId + "."));
}
else
{
    if (setupText.Length > 0 && !setupText.EndsWith("\n")) setupText += "\n";
    setupText += "ServerModSetup(\"" + fileId + "\")\n";
    File.WriteAllText(setup, setupText);
    if (!setupExisted) FixOwner(setup);
    ScriptConsole.WriteLine((object)("Added ServerModSetup(\"" + fileId + "\") to mods/dedicated_server_mods_setup.lua."));
}

// 2. Enable it in every shard of the cluster (a shard is a folder with a server.ini).
string cluster = Path.Combine(root, "DoNotStarveTogether", "Cluster_1");
var shards = Directory.Exists(cluster)
    ? Directory.GetDirectories(cluster).Where(d => File.Exists(Path.Combine(d, "server.ini"))).ToList()
    : new System.Collections.Generic.List<string>();
if (shards.Count == 0) shards.Add(Path.Combine(cluster, "Master"));
foreach (var shard in shards)
{
    string overrides = Path.Combine(shard, "modoverrides.lua");
    Refuse(overrides);
    Directory.CreateDirectory(shard);
    string shardName = Path.GetFileName(shard);
    bool existed = File.Exists(overrides);
    string text = existed ? File.ReadAllText(overrides) : "";
    string key = "[\"workshop-" + fileId + "\"]";
    if (Regex.IsMatch(text, @"\[\s*[""']workshop-" + fileId + @"[""']\s*\]"))
    {
        // Already listed (the owner may have set options): make sure it is enabled.
        int start = Regex.Match(text, @"\[\s*[""']workshop-" + fileId + @"[""']\s*\]").Index;
        int open = text.IndexOf('{', start);
        int close = open < 0 ? -1 : MatchingBrace(text, open);
        if (open >= 0 && close > open)
        {
            string entry = text.Substring(open, close - open + 1);
            string fixedEntry = Regex.IsMatch(entry, @"enabled\s*=\s*false")
                ? Regex.Replace(entry, @"enabled\s*=\s*false", "enabled=true")
                : entry;
            if (fixedEntry != entry)
            {
                File.WriteAllText(overrides, text.Substring(0, open) + fixedEntry + text.Substring(close + 1));
                ScriptConsole.WriteLine((object)("Enabled workshop-" + fileId + " in " + shardName + "/modoverrides.lua."));
            }
            else ScriptConsole.WriteLine((object)(shardName + "/modoverrides.lua already enables workshop-" + fileId + "."));
        }
        continue;
    }

    string line = "  " + key + "={ configuration_options={  }, enabled=true },";
    var ret = Regex.Match(text, @"return\s*\{");
    if (!ret.Success)
    {
        text = "return {\n" + line + "\n}\n";
    }
    else
    {
        int at = ret.Index + ret.Length;
        text = text.Substring(0, at) + "\n" + line + text.Substring(at);
    }
    File.WriteAllText(overrides, text);
    if (!existed) FixOwner(overrides);
    ScriptConsole.WriteLine((object)("Enabled workshop-" + fileId + " in " + shardName + "/modoverrides.lua."));
}
ScriptConsole.WriteLine((object)"The server downloads and loads the mod the next time it starts.");

// Index of the brace that closes the one at 'open', skipping Lua strings and comments.
int MatchingBrace(string s, int open)
{
    int depth = 0;
    for (int i = open; i < s.Length; i++)
    {
        char c = s[i];
        if (c == '"' || c == '\'')
        {
            char q = c;
            for (i++; i < s.Length && s[i] != q; i++) if (s[i] == '\\') i++;
            continue;
        }
        if (c == '-' && i + 1 < s.Length && s[i + 1] == '-')
        {
            while (i < s.Length && s[i] != '\n') i++;
            continue;
        }
        if (c == '{') depth++;
        else if (c == '}' && --depth == 0) return i;
    }
    return -1;
}

// The monitor runs this script with full rights in a folder the server account can write to. A link (symbolic link or
// junction) anywhere between the service root and a path the script reads, writes or deletes could point it at any
// file on the host, so such a path is refused. A path that does not exist yet passes (it is created below the check).
string Linked(string path)
{
    var cmp = System.OperatingSystem.IsWindows() ? StringComparison.OrdinalIgnoreCase : StringComparison.Ordinal;
    var top = Path.GetFullPath(root).TrimEnd(Path.DirectorySeparatorChar, Path.AltDirectorySeparatorChar);
    var full = Path.GetFullPath(path);
    if (!full.StartsWith(top + Path.DirectorySeparatorChar, cmp)) return Path.GetFileName(path) + " is outside the service folder";
    var current = top;
    foreach (var part in full.Substring(top.Length).Split(new[] { Path.DirectorySeparatorChar }, StringSplitOptions.RemoveEmptyEntries))
    {
        current = Path.Combine(current, part);
        var info = new FileInfo(current);
        // LinkTarget is read from the link itself, so a dangling link is caught too.
        if (info.LinkTarget != null || (info.Exists || Directory.Exists(current)) && (File.GetAttributes(current) & FileAttributes.ReparsePoint) != 0)
            return Path.GetRelativePath(top, current) + " is a link";
        if (!info.Exists && !Directory.Exists(current)) break;
    }
    return null;
}

void Refuse(string path)
{
    var reason = Linked(path);
    if (reason != null) throw new Exception("The mod was not added: " + reason + ". The script does not follow links; replace it with a normal file or folder.");
}

// A file this script creates belongs to the monitor; give it to the server's account like the rest of the root.
void FixOwner(string path)
{
    try { Globals.OperatingSystem.SetFileOwnerAutoDetect(path); }
    catch (Exception ex) { ScriptConsole.WriteLine((object)("Could not set the owner of " + Path.GetFileName(path) + ": " + ex.Message)); }
}

using System;
using System.IO;
using System.Linq;
using System.Text.RegularExpressions;

var Globals = new TCAdmin.Scripting.Engines.Addons.CSharpGameGlobals(); // DO NOT MODIFY THIS LINE

// Removes the Workshop mod from mods/dedicated_server_mods_setup.lua and from every shard's modoverrides.lua,
// then deletes the copies the server downloaded (ugc_mods/<cluster>/<shard>/content/322330/<id> and the legacy
// mods/workshop-<id>). The change applies the next time the server starts.
string fileId = Convert.ToString(Dynamic.FileId).Trim();
if (!Regex.IsMatch(fileId, "^[0-9]+$")) throw new Exception("Unexpected Workshop id: " + fileId);
string root = (string)ThisService.RootDirectory;

string setup = Path.Combine(root, "mods", "dedicated_server_mods_setup.lua");
if (Allowed(setup) && File.Exists(setup))
{
    string text = File.ReadAllText(setup);
    string updated = Regex.Replace(text, @"^[ \t]*ServerModSetup\(\s*[""']" + fileId + @"[""']\s*\)[ \t]*\r?\n?", "", RegexOptions.Multiline);
    if (updated != text)
    {
        File.WriteAllText(setup, updated);
        ScriptConsole.WriteLine((object)("Removed ServerModSetup(\"" + fileId + "\") from mods/dedicated_server_mods_setup.lua."));
    }
}

string cluster = Path.Combine(root, "DoNotStarveTogether", "Cluster_1");
if (Directory.Exists(cluster))
{
    foreach (var shard in Directory.GetDirectories(cluster))
    {
        string overrides = Path.Combine(shard, "modoverrides.lua");
        if (!Allowed(overrides) || !File.Exists(overrides)) continue;
        string text = File.ReadAllText(overrides);
        var key = Regex.Match(text, @"\[\s*[""']workshop-" + fileId + @"[""']\s*\]\s*=\s*");
        if (!key.Success) continue;
        int open = key.Index + key.Length;
        if (open >= text.Length || text[open] != '{') continue;
        int close = MatchingBrace(text, open);
        if (close < 0) { ScriptConsole.WriteLine((object)("Could not parse " + Path.GetFileName(shard) + "/modoverrides.lua; remove workshop-" + fileId + " by hand.")); continue; }
        int end = close + 1;
        // Drop the separator after the entry and the rest of its line.
        while (end < text.Length && (text[end] == ' ' || text[end] == '\t')) end++;
        if (end < text.Length && (text[end] == ',' || text[end] == ';')) end++;
        while (end < text.Length && (text[end] == ' ' || text[end] == '\t')) end++;
        if (end < text.Length && text[end] == '\r') end++;
        if (end < text.Length && text[end] == '\n') end++;
        int start = key.Index;
        while (start > 0 && (text[start - 1] == ' ' || text[start - 1] == '\t')) start--;
        File.WriteAllText(overrides, text.Substring(0, start) + text.Substring(end));
        ScriptConsole.WriteLine((object)("Removed workshop-" + fileId + " from " + Path.GetFileName(shard) + "/modoverrides.lua."));
    }
}

// The server's own downloads.
var copies = new System.Collections.Generic.List<string> { Path.Combine(root, "mods", "workshop-" + fileId) };
string ugc = Path.Combine(root, "ugc_mods");
if (Directory.Exists(ugc))
{
    foreach (var clusterDir in Directory.GetDirectories(ugc))
        foreach (var shardDir in Directory.GetDirectories(clusterDir))
            copies.Add(Path.Combine(shardDir, "content", "322330", fileId));
}
foreach (var dir in copies.Where(d => Allowed(d) && Directory.Exists(d)))
{
    try { Directory.Delete(dir, true); ScriptConsole.WriteLine((object)("Removed " + Path.GetRelativePath(root, dir))); }
    catch (Exception ex) { ScriptConsole.WriteLine((object)("Could not remove " + Path.GetRelativePath(root, dir) + " (" + ex.Message + ").")); }
}
ScriptConsole.WriteLine((object)"The mod is no longer loaded from the next server start.");

