bool Allowed(string path)
{
    var reason = Linked(path);
    if (reason == null) return true;
    ScriptConsole.WriteLine((object)("Skipped " + Path.GetFileName(path) + ": " + reason + " (the script does not follow links)."));
    return false;
}

